using FluentValidation; using JTradeERP.Application.Common.Exceptions; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Security; using MediatR;
namespace JTradeERP.Application.Features.Security.Administration.UpdateRole;
public sealed record UpdateRoleCommand(Guid Id,string Name):IRequest<UpdateRoleResponse>; public sealed record UpdateRoleResponse(Guid Id,string Name);
public sealed class UpdateRoleValidator:AbstractValidator<UpdateRoleCommand>{public UpdateRoleValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(100);}}
public sealed class UpdateRoleHandler(IApplicationDbContext db,ICurrentUserService actor):IRequestHandler<UpdateRoleCommand,UpdateRoleResponse>{public async Task<UpdateRoleResponse> Handle(UpdateRoleCommand r,CancellationToken ct){var role=db.Roles.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Role was not found.");if(db.Roles.Any(x=>x.Id!=r.Id&&x.Name==r.Name.Trim()))throw new ConflictException("Role name already exists.");var old=role.Name;role.Rename(r.Name);SecurityAuditWriter.Add(db,actor.UserId,"RoleRenamed","Role",role.Id.ToString(),old,role.Name);await db.SaveChangesAsync(ct);return new(role.Id,role.Name);}}
public static class UpdateRoleEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapPut("/roles/{id:guid}",async(Guid id,UpdateRoleCommand c,ISender s,CancellationToken t)=>Results.Ok(await s.Send(c with{Id=id},t))).RequirePermission("Admin.Roles.Manage",Capability.Full);}
